import sys
input = sys.stdin.readline

n, m = map(int, input().split())
edges = [list(map(int, input().split())) for _ in range(m)]

adj = [[] for _ in range(n + 1)]
for u, v in edges:
    adj[u].append(v)
radj = [[] for _ in range(n + 1)]
for u in range(1, n + 1):
    for v in adj[u]:
        radj[v].append(u)
order = []
seen = [False] * (n + 1)
pos = [0] * (n + 1)
for s in range(1, n + 1):
    if seen[s]:
        continue
    seen[s] = True
    stack = [s]
    while stack:
        v = stack[-1]
        if pos[v] < len(adj[v]):
            w = adj[v][pos[v]]
            pos[v] += 1
            if not seen[w]:
                seen[w] = True
                stack.append(w)
        else:
            order.append(v)
            stack.pop()
comp = [-1] * (n + 1)
comp_count = 0
for s in reversed(order):
    if comp[s] != -1:
        continue
    comp[s] = comp_count
    stack = [s]
    while stack:
        v = stack.pop()
        for w in radj[v]:
            if comp[w] == -1:
                comp[w] = comp_count
                stack.append(w)
    comp_count += 1
sizes = [0] * comp_count
for v in range(1, n + 1):
    sizes[comp[v]] += 1
sizes.sort(reverse=True)
print(comp_count)
print(*sizes)

