#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <functional>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) adj[e[0]].push_back((int)e[1]);
    const int NN = (int)(n);
    vector<vector<int>> radj(NN + 1);
    for (int u = 1; u <= NN; u++) {
        for (int v : adj[u]) radj[v].push_back(u);
    }
    vector<int> order, pos(NN + 1, 0);
    vector<char> seen(NN + 1, 0);
    for (int s = 1; s <= NN; s++) {
        if (seen[s]) continue;
        seen[s] = 1;
        vector<int> stack = {s};
        while (!stack.empty()) {
            int v = stack.back();
            if (pos[v] < (int)adj[v].size()) {
                int w = adj[v][pos[v]++];
                if (!seen[w]) {
                    seen[w] = 1;
                    stack.push_back(w);
                }
            } else {
                order.push_back(v);
                stack.pop_back();
            }
        }
    }
    vector<int> comp(NN + 1, -1);
    int compCount = 0;
    for (size_t i = order.size(); i-- > 0;) {
        int s = order[i];
        if (comp[s] != -1) continue;
        comp[s] = compCount;
        vector<int> stack = {s};
        while (!stack.empty()) {
            int v = stack.back();
            stack.pop_back();
            for (int w : radj[v]) {
                if (comp[w] == -1) {
                    comp[w] = compCount;
                    stack.push_back(w);
                }
            }
        }
        compCount++;
    }
    vector<long long> sizes(compCount, 0);
    for (int v = 1; v <= NN; v++) sizes[comp[v]]++;
    sort(sizes.begin(), sizes.end(), greater<long long>());
    cout << compCount << "\n";
    for (size_t i = 0; i < sizes.size(); i++) cout << (i ? " " : "") << sizes[i];
    cout << "\n";

    return 0;
}

